    res=[]  # (frame, g_start, g_end, nt_len, prot)
    L=len(s)
    for frame in range(3):
        i=frame
        stops=[]
        while i+2 < L:
            c=s[i:i+3]
            if c in ('TAA','TAG','TGA'):
                stops.append(i)
            i+=1
        # scan for ATG not followed by stop before next stop
        i=frame
        while i+2 < L:
            if s[i:i+3]=='ATG':
                j=i
                ok=True
