STOPS=('TAA','TAG','TGA')
def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]

def find_orfs(s, min_aa=30):
    L=len(s); res=[]
    for frame in range(3):
        i=frame
        while i+2 < L:
            if s[i:i+3]=='ATG':
                j=i
                while j+2 < L:
                    if s[j:j+3] in STOPS: break
                    j+=3
                if j+2 < L and s[j:j+3] in STOPS:
                    naa=(j+3-i)//3 - 1
                    if naa>=min_aa:
                        prot=''.join(tab[s[k:k+3]] for k in range(i,j+3,3))
                        res.append((frame+1, i+1, j+3, j+3-i, naa, prot))
            i+=3
    return res

